class SortedList<T extends Comparable<T>> {
  final List<T> _items = [];

  void add(T item) {
    _items.add(item);
    _items.sort((a, b) => a.compareTo(b));
  }

  T get first => _items.first;
}

void main() {
  final sl = SortedList<int>(); // int implements Comparable<int>
  sl.add(3);
  sl.add(1);
  sl.add(2);
  print(sl.first); // 1
}

