Stream<int> count(int n) async* {
  for (var i = 1; i <= n; i++) {
    await Future.delayed(Duration(milliseconds: 100));
    yield i;
  }
}

Future<void> main() async {
  await for (final i in count(3)) {
    print(i); // 1, 2, 3 with 100ms gaps
  }
}

Future<void> run() async {
  try {
    final data = await fetchData();
    process(data);
  } on TimeoutException catch (e) {
    print('timeout: $e');
  } on FormatException catch (e) {
    print('format: $e');
  } catch (e, st) {
    print('unexpected: $e\n$st');
  } finally {
    cleanup();
  }
}

import 'dart:io';

Future<void> writeLog(String msg) async {
  final file = File('log.txt');
  await file.writeAsString('${DateTime.now()}: $msg\n', mode: FileMode.append);
}

Future<String> readLog() async {
  final file = File('log.txt');
  return await file.readAsString();
}

import 'dart:isolate';

int heavyCompute(int n) {
  var sum = 0;
  for (var i = 0; i < n; i++) {
    sum += i * i;
  }
  return sum;
}

Future<void> main() async {
  final result = await Isolate.run(() => heavyCompute(100000000));
  print(result); // computed in parallel, no UI jank
}

